function getSymantecEndpointTranslation(key, lang) {
    return (symantecendpointTranslations[lang] && symantecendpointTranslations[lang][key]) ||
           (symantecendpointTranslations.en && symantecendpointTranslations.en[key]) || null;
}

function applySymantecEndpointTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.symantec-endpoint.") || key.startsWith("review.common."))) {
            const translation = getSymantecEndpointTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} symantec-endpoint translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applySymantecEndpointTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applySymantecEndpointTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applySymantecEndpointTranslations(window.i18n?.getCurrentLanguage() || "en");
}
